CREATE TABLE EKINNRHRONDA (OID INT IDENTITY(1,1) PRIMARY KEY, ADNCENATE INT NOT NULL, SEMANA INT NOT NULL, ANIO INT NOT NULL, FECHAINICIO DATETIME2 NOT NULL, FECHAFINAL DATETIME2 NULL, RESPONSABLEID INT NOT NULL, RESPONSABLENOMBRE VARCHAR(180) NOT NULL, ESTADO VARCHAR(20) NOT NULL, TOTALHABITACIONES INT NOT NULL, HABITACIONESREGISTRADAS INT NOT NULL DEFAULT 0, OBSERVACIONES VARCHAR(1000) NULL, CREADOPOR INT NOT NULL, FECHACREA DATETIME2 NOT NULL, FECHAACT DATETIME2 NOT NULL);
CREATE UNIQUE INDEX UX_RH_RONDA_ACTIVA ON EKINNRHRONDA (ADNCENATE, SEMANA, ANIO) WHERE ESTADO = 'EN_PROGRESO';
CREATE TABLE EKINNRHREGISTRO (OID INT IDENTITY(1,1) PRIMARY KEY, EKINNRHRONDA INT NOT NULL, EKINNRHHABITACION INT NOT NULL, EKINNRHSERVICIO INT NOT NULL, OBSERVACIONES VARCHAR(1000) NULL, FECHAREGISTRO DATETIME2 NOT NULL, REGISTRADOPOR INT NOT NULL, CONSTRAINT UQ_RH_REGISTRO UNIQUE (EKINNRHRONDA, EKINNRHHABITACION));
CREATE TABLE EKINNRHREGISTROEQUIPO (OID INT IDENTITY(1,1) PRIMARY KEY, EKINNRHREGISTRO INT NOT NULL, TIPOEQUIPO VARCHAR(40) NOT NULL, ESTADO VARCHAR(20) NOT NULL, OBSERVACION VARCHAR(500) NULL, CONSTRAINT UQ_RH_REGISTRO_EQUIPO UNIQUE (EKINNRHREGISTRO, TIPOEQUIPO));
CREATE TABLE EKINNRHALERTA (OID INT IDENTITY(1,1) PRIMARY KEY, EKINNRHRONDA INT NOT NULL, EKINNRHHABITACION INT NOT NULL, TIPOEQUIPO VARCHAR(40) NOT NULL, ESTADOANTERIOR VARCHAR(20) NOT NULL, ESTADOACTUAL VARCHAR(20) NOT NULL, TIPOALERTA VARCHAR(30) NOT NULL, RESUELTA BIT NOT NULL DEFAULT 0, FECHAGENERACION DATETIME2 NOT NULL, FECHARESOLUCION DATETIME2 NULL, RESUELTAPOR INT NULL, OBSRESOLUCION VARCHAR(1000) NULL);
